"""Separate draft supportive scripts; never combine medicines across phases."""
import json,copy
from pathlib import Path
R=Path(__file__).resolve().parents[1]
def med(name,dose,timing,note=''):return dict(name=name,dose=dose,timing=timing,note=note)
AC=[med('Aprepitant','125 mg orally','Day 1'),med('Ondansetron','16 mg orally','Day 1','Individual dose / QT / hepatic review'),med('Dexamethasone','12 mg orally','Day 1','No routine Days 2–4 dexamethasone in this NCCP AC antiemetic row'),med('Olanzapine','5 mg orally','Days 1–4','Review sedation, falls, interactions and glucose'),med('Aprepitant','80 mg orally daily','Days 2–3'),med('Metoclopramide','10 mg orally up to three times daily','Subsequent days: duration and use to be confirmed','Caution with olanzapine: additive extrapyramidal effects; adjust / avoid for individual contraindications')]
LOW=[med('Ondansetron','8 mg orally','On treatment day','Review QT, constipation and hepatic dosing; reconcile any steroid already prescribed'),med('Metoclopramide','10 mg orally up to three times daily as needed','Subsequent days: duration to be confirmed','Assess contraindications, renal function and interactions')]
CARBO=[x for x in copy.deepcopy(AC) if x['name']!='Olanzapine'];CARBO[2]['note']='Reconcile chemotherapy premedication steroids';CARBO.append(med('Dexamethasone','8 mg orally daily','Days 2–4','Carboplatin AUC ≥4 antiemetic row; reconcile total steroid exposure'));CARBO[-2]['note']='Individual contraindications, renal function and duration review'
TAX=['First paclitaxel dose: dexamethasone 8 mg IV, chlorphenamine 10 mg IV and famotidine 20 mg IV, each 30 minutes before treatment (NCCP suggested table).','From Day 8 onward: chlorphenamine 10 mg IV and famotidine 20 mg IV 30 minutes before treatment. Routine dexamethasone may be omitted after the first dose; prior reaction or increased risk requires consultant review.','Famotidine may be omitted under the consultant/local plan if appropriate. A prior reaction requires a separate rechallenge assessment; do not reuse the standard draft automatically.']
def phase(id,label,agents,risk,rows,notes,source_page):return dict(id=id,label=label,active_medicines=agents,emetogenic_risk=risk,medicines=rows,additional_support=notes,source_page=source_page)
D={
'00485':[phase('ac','Phase 1 · dose-dense AC',['Doxorubicin','Cyclophosphamide'],'High · AC',AC,['G-CSF is required for every dose-dense AC cycle. Prescribe product, dose and timing separately under the approved local plan.','This script applies only to AC. It is replaced when weekly paclitaxel starts.'],5),phase('paclitaxel','Phase 2 · weekly paclitaxel',['Paclitaxel'],'Low',LOW,TAX,5)],
'00815':[phase('combination','First 12 weeks · paclitaxel + trastuzumab',['Paclitaxel','Trastuzumab'],'Low',LOW,TAX+['Trastuzumab formulation and observation instructions remain separate from taxane premedication.'],6),phase('trastuzumab','Adjuvant continuation · trastuzumab alone',['Trastuzumab'],'Minimal',[],['Routine prophylactic antiemetics and paclitaxel premedicines are not carried into this phase. Treat prior nausea / infusion reactions under an individual plan.','Continue HER2 cardiac monitoring; ending paclitaxel does not end echo surveillance.'],6)],
'00659':[phase('tdm1','Adjuvant T-DM1',['Trastuzumab emtansine'],'Low',LOW,['Premedicines are not usually required. Prior infusion reactions need individual review.','Check platelets, liver results and cardiac status. Verify T-DM1, not trastuzumab alone or T-DXd.'],5)],
'00892':[phase('ribociclib','Adjuvant ribociclib + endocrine therapy',['Ribociclib','Non-steroidal aromatase inhibitor ± ovarian suppression'],'Oral minimal to low',[],['No default QT-prolonging antiemetic is generated. Pharmacy must choose symptom treatment after reviewing ECG, electrolytes and interacting medicines.','Ribociclib Days 1–21; Days 22–28 off. Endocrine therapy continues separately.','Bloods every 2 weeks for cycles 1–2, then before the next four cycles; ECG baseline and around C1D14; further checks as indicated.','The optional local D25–26 review window does not replace early checks or authorise restarting.'],6)],
'00936':[phase('combination','Tucatinib + capecitabine + trastuzumab',['Tucatinib','Capecitabine','Trastuzumab'],'Tucatinib / capecitabine oral minimal to low; trastuzumab minimal',[],['Agree a personalised antiemetic and diarrhoea prescription; review CYP and other interactions. No repeated IV chemotherapy premedication is assumed for these tablets.','Tucatinib continues every day; capecitabine is Days 1–14 then off Days 15–21. Confirm separate hold / restart instructions.','Premedicines are not usually required. If prior hypersensitivity, consider paracetamol / antihistamine under the clinician plan.','Explain when to hold capecitabine and call for diarrhoea, mouth soreness or painful hand-foot symptoms. Assess dehydration promptly.'],10)],
'00857':[phase('carbo-day1','Phase 1 · Day 1 carboplatin / paclitaxel / pembrolizumab',['Carboplatin','Paclitaxel','Pembrolizumab'],'High · carboplatin AUC ≥4',CARBO,['Use the exact 00857 paclitaxel premedication table and reconcile total dexamethasone exposure.','This Day 1 carboplatin script must not automatically repeat on paclitaxel-only Days 8 and 15.'],0),phase('taxane-weekly','Phase 1 · Days 8 and 15 paclitaxel',['Paclitaxel'],'Low',LOW,['Use the 00857 paclitaxel premedication / prior-reaction plan.','Carboplatin Day 1 delayed antiemetics are not repeated automatically on these visits.'],0),phase('ac','Phase 2 · AC + pembrolizumab',['Doxorubicin','Cyclophosphamide','Pembrolizumab'],'High · AC',AC,['This 00857 AC schedule is every 21 days, not the dose-dense 00485 schedule.','Confirm the growth-factor plan from the regimen / individual risk assessment. Pembrolizumab has its own immune-toxicity review.'],0),phase('pembro','After surgery · pembrolizumab alone',['Pembrolizumab'],'Minimal',[],['No routine chemotherapy antiemetic prophylaxis. Previous nausea / infusion reaction requires individual assessment.','Confirm q3-week or q6-week postoperative option. Immune symptoms can occur during or after treatment.'],0)]}
payload=dict(release='0.83.8',source_checked='2026-10-17',source='https://healthservice.hse.ie/documents/7180/Supportive_Care_Antiemetics_for_inclusion_NCIS_Medical_Oncology.pdf',source_table='Table 1, page 4; steroid reconciliation page 5',status='Regimen-level drafts; prescriber and oncology-pharmacy verification required',regimens=D)
(R/'data/phase-support-v0838.json').write_text(json.dumps(payload,ensure_ascii=False,indent=2)+'\n')
print('Authored separate phase-support drafts for six regimens.')
